from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import List, Optional
from database import get_db, init_db

app = FastAPI(title="BookTrack")

init_db()


class BookCreate(BaseModel):
    title: str
    author: str
    status: str = "to-read"


class BookUpdate(BaseModel):
    status: str


class BookOut(BaseModel):
    id: int
    title: str
    author: str
    status: str


@app.get("/api/books", response_model=List[BookOut])
def get_books():
    with get_db() as conn:
        rows = conn.execute(
            "SELECT id, title, author, status FROM books ORDER BY created_at DESC"
        ).fetchall()
    return [dict(r) for r in rows]


@app.post("/api/books", response_model=BookOut, status_code=201)
def add_book(book: BookCreate):
    if book.status not in ("to-read", "reading", "done"):
        raise HTTPException(400, "Invalid status. Use: to-read, reading, done")
    with get_db() as conn:
        cursor = conn.execute(
            "INSERT INTO books (title, author, status) VALUES (?, ?, ?)",
            (book.title, book.author, book.status),
        )
        book_id = cursor.lastrowid
    return {"id": book_id, "title": book.title, "author": book.author, "status": book.status}


@app.patch("/api/books/{book_id}", response_model=BookOut)
def update_status(book_id: int, update: BookUpdate):
    if update.status not in ("to-read", "reading", "done"):
        raise HTTPException(400, "Invalid status. Use: to-read, reading, done")
    with get_db() as conn:
        row = conn.execute(
            "SELECT id, title, author, status FROM books WHERE id = ?", (book_id,)
        ).fetchone()
        if not row:
            raise HTTPException(404, "Book not found")
        conn.execute(
            "UPDATE books SET status = ? WHERE id = ?", (update.status, book_id)
        )
    return {"id": book_id, "title": row["title"], "author": row["author"], "status": update.status}


@app.delete("/api/books/{book_id}", status_code=204)
def delete_book(book_id: int):
    with get_db() as conn:
        row = conn.execute(
            "SELECT id FROM books WHERE id = ?", (book_id,)
        ).fetchone()
        if not row:
            raise HTTPException(404, "Book not found")
        conn.execute("DELETE FROM books WHERE id = ?", (book_id,))
    return None

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    proxy: {
      '/api': 'http://localhost:8000'
    }
  }
})

import { useState, useEffect, useCallback } from 'react'

const API = '/api'

const STATUS_LABELS = {
  'to-read': '📚 Da leggere',
  'reading': '📖 In lettura',
  'done': '✅ Letto',
}

const STATUS_ORDER = ['to-read', 'reading', 'done']

function BookForm({ onAdd }) {
  const [title, setTitle] = useState('')
  const [author, setAuthor] = useState('')
  const [status, setStatus] = useState('to-read')
  const [error, setError] = useState('')

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!title.trim() || !author.trim()) {
      setError('Titolo e autore sono obbligatori')
      return
    }
    setError('')
    try {
      const res = await fetch(`${API}/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: title.trim(), author: author.trim(), status }),
      })
      if (!res.ok) throw new Error('Errore')
      setTitle('')
      setAuthor('')
      setStatus('to-read')
      onAdd()
    } catch {
      setError('Errore nell\'aggiunta del libro')
    }
  }

  return (
    <form onSubmit={handleSubmit} className="book-form">
      <h2>Aggiungi un libro</h2>
      {error && <p className="error">{error}</p>}
      <div className="form-row">
        <input
          type="text"
          placeholder="Titolo"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />
        <input
          type="text"
          placeholder="Autore"
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          required
        />
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="to-read">Da leggere</option>
          <option value="reading">In lettura</option>
          <option value="done">Letto</option>
        </select>
        <button type="submit">Aggiungi</button>
      </div>
    </form>
  )
}

function BookCard({ book, onStatusChange, onDelete }) {
  return (
    <div className="book-card">
      <div className="book-info">
        <h3>{book.title}</h3>
        <p className="book-author">di {book.author}</p>
      </div>
      <div className="book-actions">
        <select
          value={book.status}
          onChange={(e) => onStatusChange(book.id, e.target.value)}
          className="status-select"
        >
          {STATUS_ORDER.map((s) => (
            <option key={s} value={s}>{STATUS_LABELS[s]}</option>
          ))}
        </select>
        <button className="delete-btn" onClick={() => onDelete(book.id)}>🗑️</button>
      </div>
    </div>
  )
}

function BookList({ books, onStatusChange, onDelete }) {
  if (books.length === 0) {
    return <p className="empty">Nessun libro aggiunto. Inizia aggiungendone uno sopra!</p>
  }

  const grouped = {}
  STATUS_ORDER.forEach((s) => { grouped[s] = [] })
  books.forEach((b) => {
    if (grouped[b.status]) grouped[b.status].push(b)
  })

  return (
    <div className="book-list">
      {STATUS_ORDER.map((status) => {
        const list = grouped[status]
        if (list.length === 0) return null
        return (
          <div key={status} className="status-group">
            <h2>{STATUS_LABELS[status]} ({list.length})</h2>
            {list.map((book) => (
              <BookCard
                key={book.id}
                book={book}
                onStatusChange={onStatusChange}
                onDelete={onDelete}
              />
            ))}
          </div>
        )
      })}
    </div>
  )
}

export default function App() {
  const [books, setBooks] = useState([])
  const [loading, setLoading] = useState(true)

  const fetchBooks = useCallback(async () => {
    try {
      const res = await fetch(`${API}/books`)
      const data = await res.json()
      setBooks(data)
    } catch (e) {
      console.error('Errore nel caricamento:', e)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchBooks()
  }, [fetchBooks])

  const handleStatusChange = async (id, newStatus) => {
    try {
      const res = await fetch(`${API}/books/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      if (!res.ok) throw new Error()
      fetchBooks()
    } catch {
      alert('Errore nell\'aggiornamento')
    }
  }

  const handleDelete = async (id) => {
    if (!confirm('Eliminare questo libro?')) return
    try {
      const res = await fetch(`${API}/books/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error()
      fetchBooks()
    } catch {
      alert('Errore nell\'eliminazione')
    }
  }

  if (loading) return <div className="app"><p>Caricamento...</p></div>

  return (
    <div className="app">
      <header>
        <h1>📚 BookTrack</h1>
        <p>Il tuo tracker libri personale</p>
      </header>
      <BookForm onAdd={fetchBooks} />
      <BookList
        books={books}
        onStatusChange={handleStatusChange}
        onDelete={handleDelete}
      />
    </div>
  )
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0f0f0f;
  color: #e0e0e0;
  min-height: 100vh;
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

header {
  text-align: center;
  margin-bottom: 2rem;
}

header h1 {
  font-size: 2.2rem;
  color: #fff;
}

header p {
  color: #888;
  margin-top: 0.25rem;
}

/* Form */
.book-form {
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 12px;
  padding: 1.5rem;
  margin-bottom: 2rem;
}

.book-form h2 {
  font-size: 1.1rem;
  margin-bottom: 1rem;
  color: #c0c0e0;
}

.form-row {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.form-row input,
.form-row select {
  flex: 1;
  min-width: 120px;
  padding: 0.6rem 0.8rem;
  border: 1px solid #333;
  border-radius: 8px;
  background: #12121a;
  color: #e0e0e0;
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.2s;
}

.form-row input:focus,
.form-row select:focus {
  border-color: #6c63ff;
}

.form-row button {
  padding: 0.6rem 1.5rem;
  background: #6c63ff;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 0.95rem;
  cursor: pointer;
  transition: background 0.2s;
  white-space: nowrap;
}

.form-row button:hover {
  background: #5a52e0;
}

.error {
  color: #ff6b6b;
  font-size: 0.85rem;
  margin-bottom: 0.75rem;
}

/* Book list */
.book-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.status-group h2 {
  font-size: 1rem;
  color: #888;
  margin-bottom: 0.75rem;
  padding-bottom: 0.25rem;
  border-bottom: 1px solid #222;
}

.book-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 10px;
  padding: 1rem 1.25rem;
  gap: 1rem;
  transition: border-color 0.2s;
}

.book-card:hover {
  border-color: #3a3a6a;
}

.book-info h3 {
  font-size: 1rem;
  color: #fff;
  font-weight: 600;
}

.book-author {
  font-size: 0.85rem;
  color: #888;
  margin-top: 0.15rem;
}

.book-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.status-select {
  padding: 0.4rem 0.6rem;
  border: 1px solid #333;
  border-radius: 6px;
  background: #12121a;
  color: #e0e0e0;
  font-size: 0.8rem;
  cursor: pointer;
  outline: none;
}

.status-select:focus {
  border-color: #6c63ff;
}

.delete-btn {
  background: none;
  border: none;
  font-size: 1.1rem;
  cursor: pointer;
  opacity: 0.4;
  transition: opacity 0.2s;
  padding: 0.2rem;
}

.delete-btn:hover {
  opacity: 1;
}

.empty {
  text-align: center;
  color: #555;
  font-size: 1rem;
  padding: 3rem 0;
}

@media (max-width: 500px) {
  .book-card {
    flex-direction: column;
    align-items: stretch;
  }

  .book-actions {
    justify-content: space-between;
  }

  .form-row {
    flex-direction: column;
  }

  .form-row input,
  .form-row select,
  .form-row button {
    min-width: unset;
    flex: unset;
  }
}
